### Objective
Build an enterprise-grade Secure Session & Token Vault in Flutter using `package:flutter_secure_storage`. Demonstrate platform-specific security configuration (`kSecAttrAccessibleAfterFirstUnlock`, Android `encryptedSharedPreferences`), the First-Run Keychain wipe pattern, defensive KeyStore recovery handling, and secure CRUD operations.

```dart
import 'dart:io';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:shared_preferences/shared_preferences.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();

  // 1. Initialize our production secure storage service
  final vaultService = SecureVaultService();
  await vaultService.initializeVault();

  runApp(SecureStorageApp(vaultService: vaultService));
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. PRODUCTION SECURE VAULT SERVICE
// ─────────────────────────────────────────────────────────────────────────────

class SecureVaultService {
  late final FlutterSecureStorage _storage;

  static const String _keyAccessToken = 'auth_access_token_jwt';
  static const String _keyRefreshToken = 'auth_refresh_token_jwt';
  static const String _keyBiometricSeed = 'biometric_crypto_seed';
  static const String _firstRunFlag = 'has_executed_first_run_wipe_v1';

  SecureVaultService() {
    // Platform-specific security configuration
    const iosOptions = IOSOptions(
      accessibility: KeychainAccessibility.after_first_unlock,
      synchronizable: false, // Prevent syncing sensitive secrets to iCloud Keychain
    );

    const androidOptions = AndroidOptions(
      encryptedSharedPreferences: true,
      resetOnError: true, // Auto-wipes corrupted keystores on firmware update bugs
    );

    _storage = const FlutterSecureStorage(
      iOptions: iosOptions,
      aOptions: androidOptions,
    );
  }

  /// Guards against stale iOS Keychain tokens surviving app reinstallation
  Future<void> initializeVault() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final isFirstRun = prefs.getBool(_firstRunFlag) ?? true;

      if (isFirstRun) {
        debugPrint('🛡️ [SECURE VAULT] First launch detected. Purging orphaned keychain entries...');
        await _storage.deleteAll();
        await prefs.setBool(_firstRunFlag, false);
      }
    } catch (e) {
      debugPrint('⚠️ [SECURE VAULT INIT ERROR] $e');
    }
  }

  // ── TOKEN MANAGEMENT ───────────────────────────────────────────────────────

  Future<void> saveTokens({
    required String accessToken,
    required String refreshToken,
  }) async {
    await Future.wait([
      _storage.write(key: _keyAccessToken, value: accessToken),
      _storage.write(key: _keyRefreshToken, value: refreshToken),
    ]);
  }

  Future<String?> getAccessToken() async {
    try {
      return await _storage.read(key: _keyAccessToken);
    } catch (e) {
      debugPrint('🚨 [KEYSTORE ERROR] Failed to decrypt access token: $e');
      return null;
    }
  }

  Future<String?> getRefreshToken() async {
    try {
      return await _storage.read(key: _keyRefreshToken);
    } catch (e) {
      debugPrint('🚨 [KEYSTORE ERROR] Failed to decrypt refresh token: $e');
      return null;
    }
  }

  Future<Map<String, String>> getAllStoredSecrets() async {
    try {
      return await _storage.readAll();
    } catch (e) {
      debugPrint('🚨 [KEYSTORE READALL ERROR] $e');
      return {};
    }
  }

  Future<void> clearSession() async {
    await _storage.delete(key: _keyAccessToken);
    await _storage.delete(key: _keyRefreshToken);
  }

  Future<void> purgeEntireVault() async {
    await _storage.deleteAll();
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. PRESENTATION LAYER
// ─────────────────────────────────────────────────────────────────────────────

class SecureStorageApp extends StatelessWidget {
  final SecureVaultService vaultService;
  const SecureStorageApp({super.key, required this.vaultService});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Secure Storage Vault',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.redAccent,
        useMaterial3: true,
      ),
      home: SecureVaultScreen(vaultService: vaultService),
    );
  }
}

class SecureVaultScreen extends StatefulWidget {
  final SecureVaultService vaultService;
  const SecureVaultScreen({super.key, required this.vaultService});

  @override
  State<SecureVaultScreen> createState() => _SecureVaultScreenState();
}

class _SecureVaultScreenState extends State<SecureVaultScreen> {
  Map<String, String> _vaultContents = {};
  bool _isLoading = false;

  @override
  void initState() {
    super.initState();
    _refreshVault();
  }

  Future<void> _refreshVault() async {
    setState(() => _isLoading = true);
    final secrets = await widget.vaultService.getAllStoredSecrets();
    setState(() {
      _vaultContents = secrets;
      _isLoading = false;
    });
  }

  Future<void> _simulateSaveLoginTokens() async {
    final timestamp = DateTime.now().millisecondsSinceEpoch;
    await widget.vaultService.saveTokens(
      accessToken: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.token_$timestamp',
      refreshToken: 'refresh_uuid_${timestamp}_secret_credentials',
    );
    await _refreshVault();
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Tokens encrypted in Hardware Keychain / Keystore!'),
          behavior: SnackBarBehavior.floating,
        ),
      );
    }
  }

  Future<void> _clearSession() async {
    await widget.vaultService.clearSession();
    await _refreshVault();
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Session tokens purged from Keychain.'),
          behavior: SnackBarBehavior.floating,
        ),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Hardware Secure Vault'),
        centerTitle: true,
      ),
      body: ListView(
        padding: const EdgeInsets.all(20),
        children: [
          _buildSecurityBanner(),
          const SizedBox(height: 20),
          _buildActionButtons(),
          const SizedBox(height: 24),
          _buildVaultContentsCard(),
        ],
      ),
    );
  }

  Widget _buildSecurityBanner() {
    return Card(
      elevation: 0,
      color: Colors.red.shade50,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: const Padding(
        padding: EdgeInsets.all(16),
        child: Row(
          children: [
            Icon(Icons.security_rounded, color: Colors.redAccent, size: 32),
            SizedBox(width: 14),
            Expanded(
              child: Text(
                'Data encrypted at rest via iOS Keychain (Secure Enclave) and Android Keystore (EncryptedSharedPreferences).',
                style: TextStyle(fontSize: 12, height: 1.4, color: Colors.redAccent, fontWeight: FontWeight.w600),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildActionButtons() {
    return Row(
      children: [
        Expanded(
          child: FilledButton.icon(
            onPressed: _simulateSaveLoginTokens,
            icon: const Icon(Icons.key_rounded),
            label: const Text('Store Tokens'),
          ),
        ),
        const SizedBox(width: 12),
        Expanded(
          child: OutlinedButton.icon(
            onPressed: _clearSession,
            style: OutlinedButton.styleFrom(foregroundColor: Colors.redAccent),
            icon: const Icon(Icons.logout_rounded),
            label: const Text('Purge Tokens'),
          ),
        ),
      ],
    );
  }

  Widget _buildVaultContentsCard() {
    return Card(
      elevation: 1,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(18),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                const Text(
                  'Encrypted KeyStore Entries',
                  style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16),
                ),
                IconButton(
                  icon: const Icon(Icons.refresh_rounded),
                  onPressed: _refreshVault,
                ),
              ],
            ),
            const Divider(),
            if (_isLoading)
              const Padding(
                padding: EdgeInsets.all(24.0),
                child: Center(child: CircularProgressIndicator()),
              )
            else if (_vaultContents.isEmpty)
              const Padding(
                padding: EdgeInsets.all(24.0),
                child: Center(
                  child: Text('Vault is empty. No hardware secrets stored.'),
                ),
              )
            else
              ..._vaultContents.entries.map((entry) {
                // Mask secret token for display
                final val = entry.value;
                final masked = val.length > 16
                    ? '${val.substring(0, 8)}••••••••${val.substring(val.length - 4)}'
                    : '••••••••';

                return ListTile(
                  contentPadding: EdgeInsets.zero,
                  leading: const Icon(Icons.lock_outline_rounded, color: Colors.redAccent),
                  title: Text(entry.key, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 13)),
                  subtitle: Text(masked, style: const TextStyle(fontFamily: 'monospace', fontSize: 11)),
                );
              }),
          ],
        ),
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Defensive Platform Options**:
   `SecureVaultService` configures `KeychainAccessibility.after_first_unlock` on iOS, ensuring tokens remain decryptable during background tasks, and sets `encryptedSharedPreferences: true` with `resetOnError: true` on Android to automatically recover from hardware keystore corruptions.
2. **First-Run iOS Keychain Cleanliness**:
   `initializeVault()` checks an unencrypted `SharedPreferences` flag. Because SharedPreferences is wiped on app uninstall while iOS Keychain persists, a fresh install triggers `_storage.deleteAll()`, purging orphaned tokens from past installations.
3. **Hardware Enclave Isolation**:
   When `_storage.write()` executes, the operating system uses hardware-backed AES keys inside the Secure Enclave or TEE. Even with root access, plaintext extraction is mathematically infeasible.
